<?php/** * Created by PhpStorm. * User: me664 * Date: 1/15/15 * Time: 6:21 PM */class HTAssets{    static $inline_css;    static $current_css_id;    static $prefix_class="ht_";    private static $_allsripts=array();    private static $_add_allsripts=array();    private static $_allstyles=array();    private static $_add_allstyles=array();    static function  init()    {        self::$current_css_id=time();        add_action('wp_footer',array(__CLASS__,'action_footer_css'));        add_action('wp_enqueue_scripts',array(__CLASS__,'do_add_scripts'));    }    static function uri($file=false){        return get_template_directory_uri().'/assets/'.$file;    }    static function build_css_class($string=false){        self::$current_css_id++;        self::$inline_css.="                .".self::$prefix_class.self::$current_css_id."{                    {$string}                }        ";        return self::$prefix_class.self::$current_css_id;    }    static function add_inline_css($string=false){        self::$inline_css.=$string;    }    static function do_add_scripts()    {        if(is_singular())        {            wp_enqueue_script('comment');            wp_enqueue_script('comment-reply');        }        if(!empty(self::$_allsripts))        {            foreach(self::$_allsripts as $key=>$value){                $v1=isset($value[1])?$value[1]:array();                $v2=isset($value[2])?$value[2]:null;                $v3=isset($value[3])?$value[3]:null;                wp_register_script($key,$value[0],$v1,$v2,$v3);            }        }        if(!empty(self::$_add_allsripts))        {            foreach(self::$_add_allsripts as $key=>$value){                wp_enqueue_script($value);            }        }        if(!empty(self::$_allstyles))        {            foreach(self::$_allstyles as $key=>$value){                $v1=isset($value[1])?$value[1]:null;                $v2=isset($value[2])?$value[2]:null;                $v3=isset($value[3])?$value[3]:null;                wp_register_style($key,$value[0],$v1,$v2,$v3);            }        }        if(!empty(self::$_add_allstyles))        {            foreach(self::$_add_allstyles as $key=>$value){                wp_enqueue_style($value);            }        }    }    static function register_scripts($scripts=array())    {        self::$_allsripts=array_merge(self::$_allsripts,$scripts);    }    static function register_css($scripts=array())    {        self::$_allstyles=array_merge(self::$_allstyles,$scripts);    }    static function add_js($scripts=array())    {        self::$_add_allsripts=array_merge(self::$_add_allsripts,$scripts);    }    static function add_css($scripts=array())    {        self::$_add_allstyles=array_merge(self::$_add_allstyles,$scripts);    }    static function action_footer_css(){        ?>        <style>            <?php echo self::$inline_css;?>        </style>    <?php    }}HTAssets::init();